export class HelpdeskProvider extends ServiceProvider<Application> {
  public readonly name: string = 'nb3-factory/helpdesk-provider';
  private reminderTimer?: NodeJS.Timeout;
  private releaseRoleScope?: () => void;

  public override register(): void {
    this.app.container.singleton(helpdeskServiceToken, () => {
      return new HelpdeskService(this.app);
    });
  }

  public override async boot(): Promise<void> {
    // Register the IT helpdesk role with the Users plugin's role-scope registry. Doing
    // this in `boot()` is what makes the role assignable from the built-in Users page
    // instead of a page of our own; the Users plugin owns the page and the assignment
    // transaction, this application owns only the role and where it is stored.
    if (
      !this.releaseRoleScope &&
      this.app.container.has(userRoleScopeRegistryToken)
    ) {
      this.releaseRoleScope = this.app.container
        .resolve(userRoleScopeRegistryToken)
        .register(createHelpdeskRoleScope());
    }
    // Sample data is provisioned here rather than in a seed: a seed runs in the
    // database task container, which deliberately refuses the user service, so
    // it cannot create the demo accounts the tickets belong to.
    try {
      await this.ensureDemoData();
    } catch (error) {
      console.warn('[helpdesk] could not provision demo data', error);
    }
  }

  public override async start(): Promise<void> {
    const service = this.app.container.resolve(helpdeskServiceToken);
    const remind = (): void => {
      void service.remindOverdueTickets().catch((error: unknown) => {
        console.warn('[helpdesk] overdue reminder run failed', error);
      });
    };
    // Run once on start so a restart does not wait a whole interval, then poll.
    remind();
    this.reminderTimer = setInterval(remind, OVERDUE_REMINDER_INTERVAL_MS);
    this.reminderTimer.unref?.();
  }

  public override async shutdown(): Promise<void> {
    if (this.reminderTimer) {
      clearInterval(this.reminderTimer);
      this.reminderTimer = undefined;
    }
    this.releaseRoleScope?.();
    this.releaseRoleScope = undefined;

async registerRoutes() {
    if (this.routesRegistered) {
        return;
    }
    for (const middleware of this.httpMiddleware) {
        await middleware.register(this.router, this);
    }
    // Every API contribution mounts into one router so `/api` answers errors and unknown paths in the standard error
    // body. It mounts before the root contributions, whose catch-alls (the SPA's `/*`) would otherwise answer an
    // unknown API path with a page.
    const api = new Hono();
    api.use('*', requestIdMiddleware());
    // The `api` section's global limits, each installed only when configured.
    installApiLimits(api, this.config.get('api'));
    // The last resort: anything no router recognized is an unexpected failure, answered with an opaque 500.
    api.onError((error, context) => apiErrorHandler(toApiError(error), context));
    const apiRouters = [];
    const roots = [];
    for (const [index, { contribution, owner }] of this.routes.entries()) {
        const router = await contribution.createRouter(this);
        if (contribution.scope === 'api') {
            apiRouters.push({
                owner: owner ?? `route contribution #${index + 1}`,
                router,
            });
        }
        else
            roots.push(router);
    }
    // The API documentation, mounted with the contributions so a plugin route under `/swagger` fails start as a
    // duplicate rather than shadowing it.
    const apiDocs = this.container.has(apiDocsToken)
        ? this.container.resolve(apiDocsToken)
        : undefined;
    if (apiDocs) {
        apiRouters.push({
            owner: '@nocobase/app-server',
            router: createApiDocsRouter(apiDocs),
        });
    }
    // Routers a runtime dispatcher forwards to are checked with the rest, at the paths they answer below `/api`. Only
    // those registered by now, during boot, are seen; they are checked here and never mounted.
    const forwardedRouters = (apiDocs?.forwardedApiRoutes.routers ?? []).map((registration) => ({
        owner: registration.owner,
        router: registration.router,
        mount: registration.prefix.slice('/api'.length),
        // A route outside the forwarded path is never reached, so it cannot shadow anything.
        includes: (path) => isForwardedTo(registration, `/api${path}`),
    }));
    // Hono lets the first matching route win without a word, so a second contribution answering the same method and
    // path would be dead code nobody notices. Checked before anything mounts, so a failed start leaves no half-built
    // router behind.
    assertNoDuplicateApiRoutes([...apiRouters, ...forwardedRouters]);
    for (const { router } of apiRouters)
        api.route('/', router);
    api.all('*', apiNotFoundHandler);
    this.router.route('/api', api);
    for (const router of roots)
        this.router.route('/', router);

## Deliberately public routes

A third-party webhook cannot present a login session, so it is public by design. Public still requires a security boundary:

```ts
router.post('/callbacks/payment', async (context) => {
  const signature = context.req.header('x-payment-signature');
  const body = await context.req.text();

  if (!signature || !verify(body, signature)) {
    return context.json({ code: 'INVALID_SIGNATURE' }, 401);
  }

  await acceptPayment(body);
  return context.json({ accepted: true }, 202);
});
```

A root route is not under `/api`, so its responses are whatever the third party's protocol expects rather than the standard `/api` body, and it is not part of the API document.

A public route under `/api`, such as a status probe or data the sign-in page reads before anyone is signed in, still declares itself, and adds `security: []` to its `describeRoute()` so the document does not claim it needs a session or an API key.

Verify the signature, and handle timestamps, replay protection, and idempotency as the third-party protocol requires. Record in a comment why the route is public. Test anonymous requests with a missing signature, a wrong signature, a valid signature, and a duplicate delivery.

